<script setup lang="ts">
type Section = { name: string; lines: string[] };
const props = defineProps<{ modelValue: string }>();
const emit = defineEmits<{ "update:modelValue": [value: string]; error: [value: string] }>();
const sections = ref<Section[]>([]); const syncing = ref(false);
function load(value: string) { const output: Section[] = []; let current: Section | undefined; for (const raw of value.replace(/\r/g, "").split("\n")) { const heading = raw.match(/^\s*\[([^\]]+)\]\s*$/); if (heading) { current = { name: heading[1], lines: [] }; output.push(current); } else if (current) current.lines.push(raw); } if (!output.length) { emit("error", "Loon 配置需要 INI 分段，例如 [Proxy Group]"); return; } syncing.value = true; sections.value = output; syncing.value = false; }
function write() { if (!syncing.value) emit("update:modelValue", sections.value.map(section => `[${section.name}]\n${section.lines.join("\n")}`.trimEnd()).join("\n\n") + "\n"); }
function section(name: string) { return sections.value.find(item => item.name.toLowerCase() === name.toLowerCase()); }
function addLine(name: string, value: string) { const target = section(name); if (target) target.lines.push(value); else sections.value.push({ name, lines: [value] }); }
watch(() => props.modelValue, load, { immediate: true }); watch(sections, write, { deep: true });
</script>
<template><section class="loon-editor"><header><div><strong>Loon 配置</strong><small>独立 INI / CONF 编辑器</small></div><div><el-button size="small" @click="addLine('Proxy Group','新策略组 = select,__LOON_ALL_NODES__,DIRECT')">添加策略组</el-button><el-button size="small" @click="addLine('Rule','DOMAIN-SUFFIX,example.com,DIRECT')">添加规则</el-button></div></header><el-scrollbar class="body"><div class="sections"><article v-for="(item, sectionIndex) in sections" :key="item.name" class="section"><div class="section-title"><el-input v-model="item.name"/><el-button link type="danger" @click="sections.splice(sectionIndex,1)">删除分段</el-button></div><div v-for="(_, lineIndex) in item.lines" :key="lineIndex" class="line"><el-input v-model="item.lines[lineIndex]" placeholder="配置行"/><el-button link type="danger" @click="item.lines.splice(lineIndex,1)">删除</el-button></div><el-button link type="primary" @click="item.lines.push('')">添加一行</el-button></article></div></el-scrollbar></section></template>
<style scoped>.loon-editor{display:flex;min-height:0;height:100%;flex-direction:column;border:1px solid var(--el-border-color);border-radius:4px}.loon-editor header,.section-title,.line{display:flex;align-items:center;gap:10px}.loon-editor header{justify-content:space-between;padding:14px;border-bottom:1px solid var(--el-border-color-lighter)}small{display:block;margin-top:4px;color:var(--el-text-color-secondary);font-size:12px}.body{min-height:0;flex:1}.sections{display:grid;gap:12px;padding:14px}.section{display:grid;gap:8px;padding:12px;border:1px solid var(--el-border-color-lighter);border-radius:4px}.section-title .el-input{max-width:260px}.line .el-input{flex:1}</style>
